<?php
// Runs only on an explicitly configured disposable database, never production.
require dirname(__DIR__).'/public/database.php';
require dirname(__DIR__).'/public/schema.php';
$cfg=appConfig();
if (!str_starts_with($cfg['db_name'] ?? '', 'itu_test_') || !in_array($cfg['db_host'] ?? '', ['127.0.0.1','localhost'],true)) {
    fwrite(STDERR,"Use a local itu_test_* database through AULIEATA_CONFIG.\n"); exit(2);
}
$pdo=appDatabase();
appSchema($pdo);
set_error_handler(function($severity,$message,$file,$line){if(error_reporting()&$severity)throw new ErrorException($message,0,$severity,$file,$line);});
$_SESSION=[];
$failures=0; $passes=0;
function check($ok,$message){if(!$ok)throw new RuntimeException($message);}
function near($a,$b,$message){check(abs($a-$b)<0.0001,$message.' ('.$a.' vs '.$b.')');}
function rejects($fn,$message){try{$fn();}catch(RuntimeException $e){if($e instanceof PDOException)throw $e;return;}throw new RuntimeException($message);}
function testCase($name,$fn){global $passes,$failures;$_SESSION=[];try{$fn();$passes++;echo "PASS $name\n";}catch(Throwable $e){$failures++;echo "FAIL $name: ".$e->getMessage()."\n";}finally{$_SESSION=[];}}
function owner($type='cafe'){global $pdo;opsExec($pdo,'INSERT INTO users(phone,password,biz_name,biz_category,location) VALUES(?,?,?,?,?)',['test-'.bin2hex(random_bytes(8)),password_hash('Integration-Only-2026',PASSWORD_DEFAULT),'Integration fixture',$type,'Тараз']);return (int)$pdo->lastInsertId();}
function item($uid,$name='Кофе',$details=[],$price=1000,$cost=400){global $pdo;opsExec($pdo,'INSERT INTO business_catalog(user_id,item_name,item_price,item_cost,category) VALUES(?,?,?,?,?)',[$uid,$name,$price,$cost,'Тест']);$id=(int)$pdo->lastInsertId();saveCatalogDetails($pdo,$uid,$id,catalogDetails(array_merge(['availability'=>'available','data_mode'=>'live','unit'=>'шт.'],$details),businessProfile($pdo,$uid)['type']));return $id;}
function day($offset=0){return (new DateTimeImmutable(opsNow()))->modify(($offset>=0?'+':'').$offset.' days')->format('Y-m-d');}
function batch($uid,$id,$quantity=10,$cost=400,$expiry=2,$condition='safe'){global $pdo;return opsSaveBatch($pdo,$uid,0,['name'=>'Тестовая партия','item_id'=>$id,'quantity'=>$quantity,'cost'=>$cost,'price'=>1000,'expires_on'=>day($expiry),'received_on'=>day(-3),'condition'=>$condition,'unit'=>'шт.'])['id'];}
function orderFor($uid,$items,$extra=[]){global $pdo;$quote=opsQuote($pdo,$uid,$items,$extra['campaign_code']??'');return opsCreateOrder($pdo,$uid,array_merge(['items'=>$items,'quote_hash'=>$quote['hash'],'request_key'=>'test-'.bin2hex(random_bytes(12))],$extra));}
function serviceFixture($uid){global $pdo;$item=item($uid,'Консультация',['kind'=>'service','duration_minutes'=>60],2000,0);$hours=[];for($i=1;$i<=7;$i++)$hours[$i]=['enabled'=>true,'start'=>'09:00','end'=>'18:00','break_start'=>'12:00','break_end'=>'13:00'];$resource=opsSaveResource($pdo,$uid,0,['name'=>'Мастер','hours'=>$hours,'service_ids'=>[$item]])['id'];return [$item,$resource];}
function appointment($uid,$item,$resource,$at,$extra=[]){global $pdo;$quote=opsQuote($pdo,$uid,[['item_id'=>$item,'quantity'=>1]]);return opsAppointmentSave($pdo,$uid,array_merge(['item_id'=>$item,'resource_id'=>$resource,'starts_at'=>$at,'quote_hash'=>$quote['hash'],'request_key'=>'book-'.bin2hex(random_bytes(12))],$extra));}
function campaign($uid,$id,$batch,$code='SALE'){global $pdo;$promotion=opsRecord($pdo,$uid,'promotion_drafts',['name'=>'Тестовая акция','source_id'=>$batch,'status'=>'published','valid_until'=>day(2),'offer_price'=>800,'min_margin'=>20,'quantity_limit'=>5,'copy'=>'Предложение']);return opsSaveCampaign($pdo,$uid,['promotion_id'=>$promotion,'item_id'=>$id,'code'=>$code]);}

testCase('stock FEFO, reservation, completion and refund are idempotent',function()use($pdo){
    $u=owner();$i=item($u,'Товар',['inventory_mode'=>'stock']);$early=batch($u,$i,2,300,1);$late=batch($u,$i,5,400,4);batch($u,$i,99,1,-1);batch($u,$i,99,1,2,'blocked');
    $q=opsQuote($pdo,$u,[['item_id'=>$i,'quantity'=>3]]);near($q['total'],3000,'total');near($q['cost'],1000,'FEFO cost');check($q['allocations'][0]['batch_id']===$early,'oldest eligible first');
    $d=['items'=>[['item_id'=>$i,'quantity'=>3]],'quote_hash'=>$q['hash'],'request_key'=>'once-'.bin2hex(random_bytes(10))];$o=opsCreateOrder($pdo,$u,$d);$again=opsCreateOrder($pdo,$u,$d);check((int)$o['id']===(int)$again['id'],'idempotent create');
    near(opsAvailable(opsItem($pdo,$u,$i),opsBatchRows($pdo,$u)),4,'free after reserve');opsOrderStatus($pdo,$u,$o['id'],'accepted');opsOrderStatus($pdo,$u,$o['id'],'completed');opsOrderStatus($pdo,$u,$o['id'],'completed');near(opsGetRecord($pdo,$u,$early,'stock_batches')['data']['quantity'],0,'deduct once');
    opsOrderStatus($pdo,$u,$o['id'],'refunded',true);opsOrderStatus($pdo,$u,$o['id'],'refunded',true);near(opsGetRecord($pdo,$u,$early,'stock_batches')['data']['quantity'],2,'restore once');
});
testCase('cancel releases stock and foreign workspace cannot mutate order',function()use($pdo){$u=owner();$other=owner();$i=item($u,'Товар',['inventory_mode'=>'stock']);batch($u,$i,2);$o=orderFor($u,[['item_id'=>$i,'quantity'=>2]]);rejects(fn()=>orderFor($u,[['item_id'=>$i,'quantity'=>1]]),'oversold');rejects(fn()=>opsOrderStatus($pdo,$other,$o['id'],'cancelled'),'cross workspace');opsOrderStatus($pdo,$u,$o['id'],'cancelled');near(opsAvailable(opsItem($pdo,$u,$i),opsBatchRows($pdo,$u)),2,'release');});
testCase('stale prices require confirmation again',function()use($pdo){$u=owner();$i=item($u);$items=[['item_id'=>$i,'quantity'=>1]];$q=opsQuote($pdo,$u,$items);opsExec($pdo,'UPDATE business_catalog SET item_price=1500 WHERE id=?',[$i]);rejects(fn()=>opsCreateOrder($pdo,$u,['items'=>$items,'quote_hash'=>$q['hash'],'request_key'=>'stale-'.bin2hex(random_bytes(10))]),'stale quote accepted');});
testCase('demo and live orders stay separate and unknown costs remain unknown',function()use($pdo){$u=owner();$live=item($u,'Реальный',[],1000,0);$demo=item($u,'Пример',['data_mode'=>'demo']);rejects(fn()=>opsQuote($pdo,$u,[['item_id'=>$live,'quantity'=>1],['item_id'=>$demo,'quantity'=>1]]),'mixed demo accepted');$q=opsQuote($pdo,$u,[['item_id'=>$live,'quantity'=>1]]);check($q['cost']===null,'unknown cost treated as zero');$o=orderFor($u,[['item_id'=>$demo,'quantity'=>1]]);opsOrderStatus($pdo,$u,$o['id'],'accepted');opsOrderStatus($pdo,$u,$o['id'],'completed');near(opsReport($pdo,$u,day(),day())['sales'],0,'demo counted');});
testCase('recipe duplicates have correct availability',function()use($pdo){$u=owner();$ingredient=item($u,'Молоко',['inventory_mode'=>'stock']);batch($u,$ingredient,1);$drink=item($u,'Напиток',['inventory_mode'=>'recipe','recipe'=>[['item_id'=>$ingredient,'quantity'=>0.4],['item_id'=>$ingredient,'quantity'=>0.1]]]);near(opsAvailable(opsItem($pdo,$u,$drink),opsBatchRows($pdo,$u)),2,'duplicate ingredient availability');});
testCase('promotion allocates its own source batch',function()use($pdo){$u=owner();$i=item($u,'Товар',['inventory_mode'=>'stock']);$other=batch($u,$i,5,900,1);$source=batch($u,$i,5,400,2);campaign($u,$i,$source);$q=opsQuote($pdo,$u,[['item_id'=>$i,'quantity'=>1]],'SALE');check((int)$q['allocations'][0]['batch_id']===$source,'discount used unrelated expensive batch');check($q['cost']<=$q['total']*0.8,'margin below promised minimum');});
testCase('a code cannot be attributed to a different product',function()use($pdo){$u=owner();$i=item($u,'Акционный',['inventory_mode'=>'stock']);$b=batch($u,$i,5);campaign($u,$i,$b);$other=item($u,'Другой');rejects(fn()=>opsQuote($pdo,$u,[['item_id'=>$other,'quantity'=>1]],'SALE'),'code accepted without target product');});
testCase('same-title promotion cannot validate an unpublished source',function()use($pdo){$u=owner();$i=item($u,'Товар',['inventory_mode'=>'stock']);$b=batch($u,$i,5);$camp=campaign($u,$i,$b);$body=opsGetRecord($pdo,$u,$camp['id'],'ops_campaign')['data'];$p=opsGetRecord($pdo,$u,$body['promotion_id'],'promotion_drafts')['data'];$p['status']='draft';opsPutRecord($pdo,$u,$body['promotion_id'],$p);$p['status']='published';opsRecord($pdo,$u,'promotion_drafts',$p);rejects(fn()=>opsQuote($pdo,$u,[['item_id'=>$i,'quantity'=>1]],'SALE'),'wrong promotion accepted');});
testCase('schedule rejects overlap and breaks and accepts adjacent visits',function()use($pdo){$u=owner('beauty');[$i,$r]=serviceFixture($u);$at=day(2).' 09:00:00';$a=appointment($u,$i,$r,$at);rejects(fn()=>appointment($u,$i,$r,day(2).' 09:30:00'),'overlap');rejects(fn()=>appointment($u,$i,$r,day(2).' 11:30:00'),'break overlap');$b=appointment($u,$i,$r,day(2).' 10:00:00');check($b['id']!==$a['id'],'adjacent booking');});
testCase('rescheduling offers the current visit window without ignoring other bookings',function()use($pdo){
    $u=owner('beauty');[$i,$r]=serviceFixture($u);$date=day(2);$a=appointment($u,$i,$r,$date.' 09:00:00');appointment($u,$i,$r,$date.' 11:00:00');
    $normal=array_column(opsSlots($pdo,$u,$r,$i,$date),'starts_at');check(!in_array($date.' 09:30:00',$normal,true),'occupied slot offered to new booking');
    $moving=array_column(opsSlots($pdo,$u,$r,$i,$date,$a['id']),'starts_at');check(in_array($date.' 09:30:00',$moving,true),'current visit blocks its own move');check(!in_array($date.' 10:30:00',$moving,true),'another visit ignored');
    rejects(fn()=>opsSlots($pdo,owner(),$r,$i,$date,$a['id']),'foreign appointment accepted');
});
testCase('order changes keep its appointment consistent',function()use($pdo){$u=owner('beauty');[$i,$r]=serviceFixture($u);$a=appointment($u,$i,$r,day(2).' 09:00:00');$body=json_decode(opsOne($pdo,'SELECT payload FROM ops_appointments WHERE id=?',[$a['id']])['payload'],true);opsOrderStatus($pdo,$u,$body['order_id'],'accepted');check(opsOne($pdo,'SELECT status FROM ops_appointments WHERE id=?',[$a['id']])['status']==='confirmed','order accepted but appointment requested');rejects(fn()=>opsOrderStatus($pdo,$u,$body['order_id'],'completed'),'future service completed');opsOrderStatus($pdo,$u,$body['order_id'],'cancelled');check(opsOne($pdo,'SELECT status FROM ops_appointments WHERE id=?',[$a['id']])['status']==='cancelled','order cancelled but slot blocked');});
testCase('cancelled reminder can be rescheduled back to the same time',function()use($pdo){$u=owner('beauty');[$i,$r]=serviceFixture($u);opsSaveSettings($pdo,$u,['auto_confirm_booking'=>true]);$q=opsQuote($pdo,$u,[['item_id'=>$i,'quantity'=>1]]);$d=['item_id'=>$i,'resource_id'=>$r,'starts_at'=>day(2).' 09:00:00','quote_hash'=>$q['hash'],'request_key'=>'remind-'.bin2hex(random_bytes(10)),'reminder_optin'=>true];$a=opsAppointmentSave($pdo,$u,$d,'telegram',12345);$d['id']=$a['id'];$d['starts_at']=day(2).' 10:00:00';opsAppointmentSave($pdo,$u,$d);$d['starts_at']=day(2).' 09:00:00';opsAppointmentSave($pdo,$u,$d);$key='appointment-'.$a['id'].'-reminder-'.substr(hash('sha256',$d['starts_at']),0,12);check(opsOne($pdo,'SELECT status FROM ops_outbox WHERE user_id=? AND ref_key=?',[$u,$key])['status']==='queued','reminder remained cancelled');});
testCase('import update and undo preserve a concurrent change',function()use($pdo){$u=owner();$i=item($u,'Кофе',['sku'=>'COF']);$draft=opsRecord($pdo,$u,'import_drafts',['target'=>'catalog','consumed'=>false]);$p=opsImportPreview($pdo,$u,['draft_id'=>$draft,'mode'=>'upsert','prices_only'=>true,'rows'=>[['name'=>'Кофе','price'=>1500,'sku'=>'COF']]]);$r=opsImportApply($pdo,$u,$p['id']);near(opsItem($pdo,$u,$i)['item_price'],1500,'updated price');opsUndo($pdo,$u,$r['audit_id']);near(opsItem($pdo,$u,$i)['item_price'],1000,'undo price');$draft=opsRecord($pdo,$u,'import_drafts',['target'=>'catalog','consumed'=>false]);$p=opsImportPreview($pdo,$u,['draft_id'=>$draft,'mode'=>'upsert','rows'=>[['name'=>'Кофе','price'=>1600,'sku'=>'COF']]]);opsExec($pdo,'UPDATE business_catalog SET item_price=1300 WHERE id=?',[$i]);rejects(fn()=>opsImportApply($pdo,$u,$p['id']),'stale import');near(opsItem($pdo,$u,$i)['item_price'],1300,'concurrent price preserved');});
testCase('operator output omits cost and private owner data',function()use($pdo){$u=owner();opsExec($pdo,'INSERT INTO ops_staff(user_id,name,role) VALUES(?,?,?)',[$u,'Оператор','operator']);$_SESSION=['staff_id'=>(int)$pdo->lastInsertId(),'staff_role'=>'operator'];$data=opsFilterOutput(['catalog'=>[['item_cost'=>600]],'stock_batches'=>[['data'=>['cost'=>600]]],'business_capacity'=>[['data'=>['cost'=>600]]],'promotion_drafts'=>[['data'=>['min_margin'=>20]]],'knowledge'=>[['data'=>['audience'=>'internal','text'=>'private']]],'telegram_messages'=>[['data'=>['owner_private'=>true,'text'=>'private']]],'tasks'=>[['data'=>['text'=>'private']]]]);check(empty($data['stock_batches'])&&empty($data['business_capacity'])&&empty($data['promotion_drafts']),'operator receives private stock data');check(empty($data['telegram_messages'])&&empty($data['tasks']),'operator receives owner material');$b=opsFilterOutput(['options'=>[['quote'=>['total'=>1000,'cost'=>600,'allocations'=>[['cost'=>600]]]]]]);check(!isset($b['options'][0]['quote']['cost'])&&!isset($b['options'][0]['quote']['allocations']),'budget leaks cost');});
testCase('revoked staff cannot keep a session',function()use($pdo){$u=owner();opsExec($pdo,'INSERT INTO ops_staff(user_id,name,role,active) VALUES(?,?,?,0)',[$u,'Оператор','operator']);$_SESSION=['staff_id'=>(int)$pdo->lastInsertId(),'staff_role'=>'operator'];rejects(fn()=>opsStaffGate($pdo,$u,'ops_load',[]),'revoked session accepted');});
testCase('import preserves omitted metadata and normalizes availability',function()use($pdo){$u=owner();$i=item($u,'Кофе',['sku'=>'COF','description'=>'Арабика','availability'=>'available']);$draft=opsRecord($pdo,$u,'import_drafts',['target'=>'catalog']);$rows=[cleanImportRow('catalog',['name'=>'Кофе','price'=>1100,'sku'=>'COF'])];$preview=opsImportPreview($pdo,$u,['draft_id'=>$draft,'mode'=>'upsert','prices_only'=>true,'rows'=>$rows]);opsImportApply($pdo,$u,$preview['id']);check(opsItem($pdo,$u,$i)['details']['availability']==='available','missing availability erased');check(opsItem($pdo,$u,$i)['details']['description']==='Арабика','missing description erased');check(cleanImportRow('catalog',['name'=>'Товар','price'=>10,'availability'=>'Нет в наличии'])['availability']==='out_of_stock','availability translation');});
testCase('pending Telegram order rechecks enablement',function()use($pdo){$u=owner();$i=item($u);$items=[['item_id'=>$i,'quantity'=>1]];$q=opsQuote($pdo,$u,$items);opsSaveChat($pdo,$u,123,['pending'=>['kind'=>'order','expires'=>time()+900,'data'=>['items'=>$items,'quote_hash'=>$q['hash'],'request_key'=>'disabled-'.bin2hex(random_bytes(10))]]]);$reply=opsBotHandle($pdo,['id'=>$u],123,'Подтверждаю',[]);check(str_contains($reply,'выключен'),'disabled order not explained');check(!opsOne($pdo,'SELECT id FROM ops_orders WHERE user_id=?',[$u]),'disabled bot created order');});
testCase('owner Telegram code is single use and private',function()use($pdo){$u=owner();opsRecord($pdo,$u,'ops_owner_code',['hash'=>hash('sha256','12345678'),'expires'=>time()+60]);$event=opsRecord($pdo,$u,'telegram',['text'=>'я владелец 12345678','chat_id'=>'123']);$r=opsBotHandle($pdo,['id'=>$u],123,'я владелец 12345678',[],$event);check(str_contains($r,'включён'),'owner login');$saved=opsGetRecord($pdo,$u,$event,'telegram')['data'];check($saved['owner_private']&&$saved['text']==='[Вход владельца]','owner login exposed');$r=opsBotHandle($pdo,['id'=>$u],124,'я владелец 12345678',[]);check(str_contains($r,'недействителен'),'code reused');});
testCase('staff role changes apply immediately',function()use($pdo){$u=owner();opsExec($pdo,'INSERT INTO ops_staff(user_id,name,role) VALUES(?,?,?)',[$u,'Сотрудник','operator']);$_SESSION=['staff_id'=>(int)$pdo->lastInsertId(),'staff_role'=>'manager'];opsStaffGate($pdo,$u,'load',[]);check($_SESSION['staff_role']==='operator','stale role');rejects(fn()=>opsStaffGate($pdo,$u,'ops_owner_apply',[]),'staff can apply owner plan');});
function race($uid,$mode,$payload){$processes=[];for($i=0;$i<2;$i++){$pipes=[];$process=proc_open([PHP_BINARY,__DIR__.'/race-worker.php',(string)$uid,$mode,base64_encode(opsJson($payload))],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);check(is_resource($process),'worker not started');$processes[]=[$process,$pipes];}foreach($processes as [$process,$pipes]){fwrite($pipes[0],"go\n");fclose($pipes[0]);}$out=[];foreach($processes as [$process,$pipes]){$raw=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$code=proc_close($process);check($code===0,'worker error '.$err);$r=json_decode($raw,true);check(is_array($r),'worker invalid output '.$raw);$out[]=$r;}return $out;}
testCase('concurrent buyers cannot oversell the last item',function()use($pdo){$u=owner();$i=item($u,'Последний',['inventory_mode'=>'stock']);batch($u,$i,1);$items=[['item_id'=>$i,'quantity'=>1]];$q=opsQuote($pdo,$u,$items);$results=race($u,'order',['items'=>$items,'quote_hash'=>$q['hash']]);check(count(array_filter($results,fn($r)=>$r['ok']))===1,'both buyers accepted or both failed');near(opsOne($pdo,'SELECT SUM(quantity) AS n FROM ops_reservations WHERE user_id=? AND active=1',[$u])['n'],1,'reserve duplicated');});
testCase('concurrent bookings cannot claim the same slot',function()use($pdo){$u=owner('beauty');[$i,$r]=serviceFixture($u);$q=opsQuote($pdo,$u,[['item_id'=>$i,'quantity'=>1]]);$results=race($u,'booking',['item_id'=>$i,'resource_id'=>$r,'starts_at'=>day(2).' 09:00:00','quote_hash'=>$q['hash']]);check(count(array_filter($results,fn($r)=>$r['ok']))===1,'overlapping requests accepted');});

testCase('supplier totals include package minimums and delivery',function()use($pdo){$u=owner();$a=opsSupplierSave($pdo,$u,['supplier'=>'A','shipping'=>200,'rows'=>[['name'=>'Молоко','match_key'=>'молоко','unit'=>'л','pack_units'=>6,'pack_price'=>3000,'min_packs'=>2]]]);opsSupplierSave($pdo,$u,['supplier'=>'B','shipping'=>0,'rows'=>[['name'=>'Молоко','match_key'=>'молоко','unit'=>'л','pack_units'=>1,'pack_price'=>600,'min_packs'=>1]]]);$offers=opsCompareSuppliers($pdo,$u,'молоко','л',7);near($offers[0]['total'],4200,'cheaper final order');near($offers[1]['total'],6200,'minimum packages and delivery');check(count(opsCompareSuppliers($pdo,$u,'молоко','кг',7))===0,'incompatible units merged');});
testCase('scenario and completed revenue use exact known costs',function()use($pdo){$u=owner();$i=item($u,'Кофе',[],1000,400);$r=opsScenario($pdo,$u,['item_id'=>$i,'quantity'=>10,'price_delta'=>100]);near($r['scenarios'][1]['gross_profit'],7000,'scenario profit');$o=orderFor($u,[['item_id'=>$i,'quantity'=>2]]);opsOrderStatus($pdo,$u,$o['id'],'accepted');opsOrderStatus($pdo,$u,$o['id'],'completed');$report=opsReport($pdo,$u,day(),day());near($report['sales'],2000,'real revenue');near($report['known_cost'],800,'real cost');near($report['gross_profit'],1200,'real margin');});
