testCase('shift task status and ticket resolution persist',function()use($pdo){$u=owner();$s=opsShiftSave($pdo,$u,['name'=>'Вечер','tasks'=>[['name'=>'Проверить холодильник']]]);opsShiftTask($pdo,$u,$s['id'],0,true);check(opsGetRecord($pdo,$u,$s['id'],'ops_shift')['data']['tasks'][0]['status']==='done','shift status');$ticket=opsTicket($pdo,$u,['chat_id'=>777,'text'=>'Нужен сотрудник']);opsSaveChat($pdo,$u,777,['ticket_id'=>$ticket]);opsTicketUpdate($pdo,$u,$ticket,['status'=>'resolved']);check(empty(opsChat($pdo,$u,777)['ticket_id']),'resolved chat remained blocked');});
testCase('outbox preserves delivered notices and detects interrupted sends',function()use($pdo){$u=owner();opsQueue($pdo,$u,777,'sent-once','Тест');opsExec($pdo,"UPDATE ops_outbox SET status='sent' WHERE user_id=?",[$u]);opsQueue($pdo,$u,777,'sent-once','Ещё раз');check(opsOne($pdo,'SELECT status FROM ops_outbox WHERE user_id=?',[$u])['status']==='sent','delivered requeued');opsQueue($pdo,$u,777,'interrupted','Тест');opsExec($pdo,"UPDATE ops_outbox SET status='sending',due_at=? WHERE user_id=? AND ref_key='interrupted'",[day(-1).' 00:00:00',$u]);opsRunOutbox($pdo,100);check(opsOne($pdo,"SELECT status FROM ops_outbox WHERE user_id=? AND ref_key='interrupted'",[$u])['status']==='unknown','interrupted send retried');});

testCase('capacity campaign requires the promised booking day',function()use($pdo){$u=owner('beauty');[$i,$r]=serviceFixture($u);$source=opsRecord($pdo,$u,'business_capacity',['name'=>'Окно мастера','item_id'=>$i,'date'=>day(2),'quantity'=>3,'unit'=>'запись','cost'=>400,'price'=>2000]);$promo=opsRecord($pdo,$u,'promotion_drafts',['name'=>'Окно со скидкой','source_id'=>$source,'status'=>'published','valid_until'=>day(2),'offer_price'=>1000,'min_margin'=>20,'quantity_limit'=>3,'copy'=>'По записи']);opsSaveCampaign($pdo,$u,['promotion_id'=>$promo,'item_id'=>$i,'code'=>'WINDOW']);$q=opsQuote($pdo,$u,[['item_id'=>$i,'quantity'=>1]],'WINDOW');$d=['item_id'=>$i,'resource_id'=>$r,'starts_at'=>day(3).' 09:00:00','quote_hash'=>$q['hash'],'campaign_code'=>'WINDOW','request_key'=>'window-'.bin2hex(random_bytes(10))];rejects(fn()=>opsAppointmentSave($pdo,$u,$d),'campaign used on wrong day');$d['starts_at']=day(2).' 09:00:00';check(!empty(opsAppointmentSave($pdo,$u,$d)['id']),'valid campaign booking failed');});

echo "RESULT $passes passed, $failures failed\n";
exit($failures?1:0);
